    has_source_file: bool | None = Field(validation_alias=AliasChoices('has_source_file', 'hasSourceFile'), serialization_alias='hasSourceFile', default=None, description='Filter by whether the dataset was converted out of a file: true for the series a converter read from an upload, false for data written straight in (by an app, an agent, a script). Pair `false` with `notDerived` for the acquired data that came without a file')
