    color_bys: tuple[LayerLabelRenderColorBys, ...] = Field(alias='colorBys')
    active_color_by: int | None = Field(default=None, alias='activeColorBy')
    filter_bys: tuple[LayerLabelRenderFilterBys, ...] = Field(alias='filterBys')
